          </StyledFab>
        </div>
      )}

      <div className="main-cont h-screen w-screen overflow-hidden">
        <LeftDrawer
          isDesktop={isDesktop}
          setisLeftOpen={setisLeftOpen}
          isLeftOpen={isLeftOpen}
          mode={mode}
          events={events}
          onEventClick={setSelectedEvent}
        />
        <div
          className={`canvas flex flex-col relative  transition-all h-full
         ${isDesktop && isOpen ? "max-w-[70%]" : "w-full"}  
         `}
        >
          {isDesktop ? (
            <div
              className={`z-[99999]`}
            >
              <Navbart
                setSelectedEvent={setSelectedEvent}
                isLeftOpen={isLeftOpen}
                setisLeftOpen={setisLeftOpen}
                isOpen={isOpen}
                setIsOpen={setIsOpen}
                mode={mode}
                setmode={setmode}
                setcountry={setcountry}
              />
            </div>
          ) : (
            <BottomAppBar
              isSlider={isSlider}
              setisLeftOpen={setisLeftOpen}
              isLeftOpen={isLeftOpen}
              settings={settings}
              setsettings={setsettings}
              setIsSlider={setIsSlider}
              mode={mode}
              setmode={setmode}
            />
          )}
          {isDesktop && (
            <SettingsIcons
              panel={panel}
              setPanel={setPanel}
              setisLeftOpen={setisLeftOpen}
              isLeftOpen={isLeftOpen}
              setmode={setmode}
              mode={mode}
              setIsOpen={setIsOpen}
              isOpen={isOpen}
              setsettings={setsettings}
              settings={settings}
            />
          )}

          <div
            className={`absolute panel-cont   
    transition-opacity duration-500 ease-in-out 
    ${settings ? "opacity-100" : "opacity-0 pointer-events-none"}
    ${
      isDesktop
        ? "right-40 mr-20 top-[53%] -translate-y-1/2 z-[999]"
        : " h-[75vh] top-1/2 -translate-y-1/2 z-[9999]  left-1/2 -translate-x-1/2"
    }`}
          >
            <SettingsPanel
              isDesktop={isDesktop}
              setSelectedEvent={setSelectedEvent}
              yearRange={yearRange}
              setLimit={setLimit}
              setsettings={setsettings}
              pages={pages}
              currentPage={currentPage}
              setCurrentPage={setCurrentPage}
              limit={limit}
              filterTotalEvents={filterTotalEvents}
              totalEvents={totalEvents}
              setYearRange={setYearRange}
              selectedCategory={selectedCategory}
              country={country}
              setcountry={setcountry}
              setSelectedCategory={setSelectedCategory}
              mode={mode}
            />
          </div>

          {isDesktop ? (
            <Drawer
              setIsOpen={setIsOpen}
              mode={mode}
              isOpen={isOpen}
              randomEvents={randomEvents}
              randomizeEvents={randomizeEvents}
              onEventClick={setSelectedEvent}
            />
          ) : (
            <AlternativeDrawer
              events={randomEvents}
              mode={mode}
              onEventClick={setSelectedEvent}
              isSlider={isSlider}
              randomizeEvents={randomizeEvents}
              setIsSlider={setIsSlider}
            />
          )}
          <div className="relative  h-full w-full">
            <Backdrop open={open} setOpen={setOpen} />
            <MapComponent
              events={events}
              // country={country}
              mode={mode}
              selectedEvent={selectedEvent}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

import dbConnect from "@/app/lib/mongoose";
import MapVisitor from "@/app/models/MapVisitors";
import { NextResponse } from "next/server";

export async function GET(req, res) {
  try {
    await dbConnect();
    // await MapVisitor.deleteMany({ ip: "127.0.0.1" });
    const users = await MapVisitor.find({});
    // res.json(users);
    return NextResponse.json(users);
    console.log("Request hit sending data for all users");
  } catch (err) {
    console.log("error message", err);
    return NextResponse.json(
      { success: false, error: err.message },
      { status: 500 }
    );
  }
}

export async function POST(req) {
  try {
    const { pathName } = await req.json();
    const headers = req.headers;

    const userAgent = headers.get("user-agent") || "unknown";

    let ip =
      headers.get("x-forwarded-for")?.split(",")[0] ||
      headers.get("remote-addr") ||
      "unknown";


    if (ip.startsWith("::ffff:")) {
      ip = ip.replace("::ffff:", "");
    }

    await dbConnect();

    await MapVisitor.create({
      pathName,
      userAgent,
      ip,
    });

    const total = await MapVisitor.countDocuments();

    return NextResponse.json({ success: true, total });
  } catch (err) {
    return NextResponse.json(
      {
        success: false,
        error: err.message,
      },
      { status: 500 }
    );
  }
}

