      setTimeout(() => {
        setShowIcons(false);
        setAnimating(false);
      }, 300); // match animation duration
    }
  }, [panel]);

  return (
    <>
      <style>{fabAnimations}</style>

      {showIcons ? (
        <div
          className="absolute flex flex-col items-end gap-2 bottom-[18%] right-6 z-[999]"
          style={{
